using System.Collections.Generic;
using Game.Player;
using Game.Utils;
using UnityEngine;

namespace Game.Enemies
{
    /// <summary>Genera enemigos periódicamente mientras el jugador siga vivo.</summary>
    public class EnemySpawner : MonoBehaviour
    {
        [SerializeField] private GameObject _enemyPrefab;

        private readonly List<GameObject> _spawned = new List<GameObject>();
        private PlayerHealth _player;
        private float _timer;

        private void Awake()
        {
            _player = FindFirstObjectByType<PlayerHealth>();
        }

        private void Update()
        {
            if (_player == null || _player.CurrentHealth <= 0) return;

            _timer += Time.deltaTime;
            if (_timer >= GameBalance.EnemySpawnInterval)
            {
                _timer = 0f;
                RemoveDestroyed();
                if (_spawned.Count >= GameBalance.MaxAliveEnemies) return;

                _spawned.Add(Instantiate(_enemyPrefab, transform.position, Quaternion.identity));
            }
        }

        private void RemoveDestroyed()
        {
            for (int i = _spawned.Count - 1; i >= 0; i--)
            {
                if (_spawned[i] == null) _spawned.RemoveAt(i);
            }
        }
    }
}
